def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid);w=len(grid[0]);seen=set()
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            stack=[(r,c)];seen.add((r,c));pts=[]
            while stack:
                x,y=stack.pop();pts.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                        seen.add((a,b));stack.append((a,b))
            colors={grid[x][y] for x,y in pts};dims=[]
            for col in colors:
                p=[(x,y) for x,y in pts if grid[x][y]==col]
                dims.append((max(x for x,y in p)-min(x for x,y in p)+1,max(y for x,y in p)-min(y for x,y in p)+1))
            v=8 if len(set(dims))==1 else 5
            for x,y in pts:out[x][y]=v
    return out

